def solve(g):
    from collections import defaultdict
    cm = defaultdict(list)
    for i,r in enumerate(g):
        for j,c in enumerate(r):
            if c: cm[c].append((i,j))
    objs_ = {}
    for v,cs in cm.items():
        mi=min(a for a,b in cs); mj=min(b for a,b in cs)
        objs_[v]=sorted((a-mi,b-mj) for a,b in cs)
    o=[[0]*len(g[0]) for _ in g]
    ti=tj=0; first=True
    for v in sorted(objs_):
        if not first:
            ti,tj = max(a for a,b in placed), max(b for a,b in placed)
        placed=[(ti+a,tj+b) for a,b in objs_[v]]
        for a,b in placed: o[a][b]=v
        first=False
    return o
